package uk.ac.ravensbourne.casevault.common;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.UUID; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
/** Assigns a non-secret correlation identifier to every response and request log context. */
@Component public class CorrelationIdFilter extends OncePerRequestFilter { public static final String HEADER="X-Correlation-ID"; @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException {String id=UUID.randomUUID().toString();MDC.put("correlationId",id);response.setHeader(HEADER,id);try{chain.doFilter(request,response);}finally{MDC.remove("correlationId");}} }
